import sys

def find_root(tree):
    in_degree = {node: 0 for node in tree}
    for children in tree.values():
        for child in children:
            in_degree[child] += 1
    for node, degree in in_degree.items():
        if degree == 0:
            return node
    return None

def merge_trees(tree1, tree2):
    root1 = find_root(tree1)
    root2 = find_root(tree2)
    if root1 != root2:
        tree1[root2] = [root1]
        tree1.update(tree2)
    return tree1

def build_tree(edges):
    tree = {}
    for u, v in edges:
        if u not in tree:
            tree[u] = []
        if v not in tree:
            tree[v] = []
        tree[u].append(v)
    return tree

def reconstruct_tree_of_life(n, edges1, edges2):
    tree1 = build_tree(edges1)
    tree2 = build_tree(edges2)
    merged_tree = merge_trees(tree1, tree2)
    root = find_root(merged_tree)
    result = []
    visited = set()

    def dfs(node, parent):
        if node in visited:
            return
        visited.add(node)
        if parent is not None:
            result.append((node, parent))
        for child in merged_tree.get(node, []):
            dfs(child, node)

    dfs(root, None)
    return result

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n, k = map(int, input[index].split())
        index += 1
        edges1 = []
        for _ in range(n - 1):
            u, v = map(int, input[index].split())
            edges1.append((u, v))
            index += 1
        edges2 = []
        for _ in range(n - 1):
            u, w = map(int, input[index].split())
            edges2.append((u, w))
            index += 1
        result = reconstruct_tree_of_life(n, edges1, edges2)
        results.append("YES\n" + "\n".join(f"{v} {u}" for u, v in result) + "\n")
    sys.stdout.write("".join(results))

main()
